<?php session_start();require_once __DIR__.'/../../src/db.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$scene=(int)($_GET['scene']??$_POST['scene']??0);$db=db();if(isset($_GET['delete'])){$q=$db->prepare("DELETE FROM hotspots WHERE id=? AND scene_id=?");$q->execute([(int)$_GET['delete'],$scene]);header('Location:?scene='.$scene);exit;}if($_SERVER['REQUEST_METHOD']==='POST'){$q=$db->prepare("INSERT INTO hotspots(scene_id,target_scene_id,label,yaw,pitch,type,content) VALUES(?,?,?,?,?,'scene','')");$q->execute([$scene,(int)$_POST['target'],trim($_POST['label']),(float)$_POST['yaw'],(float)$_POST['pitch']]);header('Location:?scene='.$scene);exit;}$q=$db->prepare("SELECT s.*,p.image,p.projection,p.stereo,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.id=?");$q->execute([$scene]);$s=$q->fetch();if(!$s)exit('Scene not found');$q=$db->prepare("SELECT ts.*,p.title panorama_title FROM tour_scenes ts JOIN panoramas p ON p.id=ts.panorama_id WHERE ts.tour_id=? AND ts.id<>? ORDER BY ts.sort_order");$q->execute([$s['tour_id'],$scene]);$targets=$q->fetchAll();$q=$db->prepare("SELECT h.*,COALESCE(ts.title,p.title) target_title FROM hotspots h LEFT JOIN tour_scenes ts ON ts.id=h.target_scene_id LEFT JOIN panoramas p ON p.id=ts.panorama_id WHERE h.scene_id=?");$q->execute([$scene]);$points=$q->fetchAll();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"><title>Hotspot editor</title></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/tours.php?edit=<?=$s['tour_id']?>">← Сцены</a></aside><main><header><div><small>VISUAL HOTSPOT EDITOR</small><h1><?=htmlspecialchars($s['title']?:$s['panorama_title'])?></h1></div></header><div class="hotspot-layout"><div><div id="hotspot-editor" data-image="<?=htmlspecialchars($s['image'])?>" data-projection="<?=htmlspecialchars($s['projection'])?>" data-stereo="<?=htmlspecialchars($s['stereo'])?>"></div><p class="hint">Поверните сцену и нажмите <b>ПОСТАВИТЬ ТОЧКУ В ЦЕНТРЕ</b>. Координаты направления заполнятся автоматически.</p><button type="button" id="capture" class="btn">⊕ ПОСТАВИТЬ ТОЧКУ В ЦЕНТРЕ</button></div><form class="editor compact" method="post"><input type="hidden" name="scene" value="<?=$scene?>"><label>Подпись<input name="label" value="Перейти" required></label><label>Целевая сцена<select name="target" required><?php foreach($targets as $t):?><option value="<?=$t['id']?>"><?=htmlspecialchars($t['title']?:$t['panorama_title'])?></option><?php endforeach;?></select></label><label>Yaw<input id="yaw" type="number" step=".1" name="yaw" value="0"></label><label>Pitch<input id="pitch" type="number" step=".1" name="pitch" value="0"></label><button class="btn" <?=!$targets?'disabled':''?>>＋ СОХРАНИТЬ HOTSPOT</button></form></div><h2>Точки сцены</h2><div class="table"><?php foreach($points as $h):?><div class="row"><div class="grow"><b><?=htmlspecialchars($h['label'])?></b><small>yaw <?=round($h['yaw'],1)?>° / pitch <?=round($h['pitch'],1)?>° → <?=htmlspecialchars($h['target_title']??'scene')?></small></div><a class="danger" href="?scene=<?=$scene?>&delete=<?=$h['id']?>" onclick="return confirm('Удалить точку?')">×</a></div><?php endforeach;?></div></main><script type="module" src="/assets/hotspot-editor.js"></script></body></html>